f='src/main/frontend/src/app/features/people/people-list.ts'
s=open(f).read()
a='''              <td data-testid="rollup-freeboard-total">{{ freeboardTotal() }}</td>
              <td colspan="18"></td>
            </tr>
'''
s=s.replace(a,a+'''            <tr>
              <th scope="row" colspan="31">Freeboard top</th>
              <td data-testid="rollup-freeboard-top">{{ freeboardTop() ?? 'n/a' }}</td>
              <td colspan="18"></td>
            </tr>
''',1)
b='''    trimmedTotal((this.people() ?? []).map((p) => ({ value: p.freeboard, hold: p.hold }))),
  );
'''
s=s.replace(b,b+'''
  // The highest freeboard among the people not on hold (n/a freeboards skipped); null (n/a) when
  // nobody has one.
  protected readonly freeboardTop = computed(() => {
    const values = (this.people() ?? [])
      .filter((p) => !p.hold)
      .map((p) => p.freeboard)
      .filter((v): v is number => v !== null);
    return values.length === 0 ? null : Math.max(...values);
  });
''',1)
open(f,'w').write(s)
EOF
grep -n "freeboardTop" $f; bin/e2e 2>&1 | tail -15

